const aug17BlogBasics = {
  'philippines-outsourced-operations-intake-design': { intro: 'An operations intake design is useful only when a busy owner can tell which requests are ready, which are incomplete, and who must decide the exception.', sections: [{ title: 'Define request readiness', paragraphs: [aug17Source[0][4], aug17Source[0][5]], checks: ['What makes an intake complete?', 'Which urgency claims need evidence?', 'Who decides the commitment?'] }, { title: 'Review queue quality', paragraphs: [aug17Source[0][6]], checks: ['Where does rework begin?', 'Which example should be added?', 'When does the rule change?'] }] },
  'philippines-virtual-assistant-sop-change-control': { intro: 'SOP change control protects a Philippines-based assistant from treating an unapproved edit as the new operating rule.', sections: [{ title: 'Separate draft from approval', paragraphs: [aug17Source[1][4], aug17Source[1][5]], checks: ['What evidence supports the change?', 'Who approves the effective version?', 'How is the prior version retained?'] }, { title: 'Test the approved step', paragraphs: [aug17Source[1][6]], checks: ['Which task confirms the change?', 'What remains an open question?', 'When is the change reviewed?'] }] },
  'philippines-remote-team-coverage-gap-review': { intro: 'Coverage-gap review turns a vague concern about availability into a record of tasks, response windows, backups, and owner decisions.', sections: [{ title: 'Describe the gap', paragraphs: [aug17Source[2][4], aug17Source[2][5]], checks: ['What task was uncovered?', 'Was the gap missed or intentional?', 'Who decides the coverage response?'] }, { title: 'Fix the boundary', paragraphs: [aug17Source[2][6]], checks: ['Which handoff repeatedly fails?', 'Is a backup sufficiently authorized?', 'What evidence supports a staffing change?'] }] },
  'philippines-outsourced-customer-support-knowledge-gaps': { intro: 'Customer-support knowledge gaps should become visible questions with ticket evidence, not improvised answers that create a new policy.', sections: [{ title: 'Collect the unanswered pattern', paragraphs: [aug17Source[3][4], aug17Source[3][5]], checks: ['Which questions repeat?', 'Where is the approved source?', 'Who owns the customer-facing answer?'] }, { title: 'Measure the approved answer', paragraphs: [aug17Source[3][6]], checks: ['Did repeat routing decrease?', 'Which guidance is obsolete?', 'What remains unresolved?'] }] },
  'philippines-admin-support-delegation-matrix': { intro: 'A delegation matrix gives admin support a practical boundary between preparing work, executing an approved step, escalating, and making a decision.', sections: [{ title: 'Name each permission', paragraphs: [aug17Source[4][4], aug17Source[4][5]], checks: ['Which action is allowed?', 'Which fields are sensitive?', 'Who owns the consequential decision?'] }, { title: 'Sample edge cases', paragraphs: [aug17Source[4][6]], checks: ['Where is the matrix ambiguous?', 'Which example should be published?', 'Who sets the effective date?'] }] },
  'philippines-outsourced-reporting-definition-register': { intro: 'A reporting definition register keeps a Philippines-based reporting lane from turning a changed source or missing value into a misleading number.', sections: [{ title: 'Make every metric reproducible', paragraphs: [aug17Source[5][4], aug17Source[5][5]], checks: ['What question does the metric answer?', 'Which period and source apply?', 'Who interprets the result?'] }, { title: 'Control definition changes', paragraphs: [aug17Source[5][6]], checks: ['Is the value missing or zero?', 'Which period is affected?', 'Who approves the external conclusion?'] }] },
  'philippines-virtual-assistant-client-follow-up-aging': { intro: 'Client follow-up aging is more useful when it distinguishes waiting for the client, waiting for the owner, missing input, and an approved next action.', sections: [{ title: 'Record why an item waits', paragraphs: [aug17Source[6][4], aug17Source[6][5]], checks: ['What was the last source-backed contact?', 'What may the assistant draft?', 'Who owns a new commitment?'] }, { title: 'Close with evidence', paragraphs: [aug17Source[6][6]], checks: ['What caused the aging?', 'What response proves resolution?', 'Who confirms that pursuit ends?'] }] },
  'philippines-remote-staff-task-sampling': { intro: 'Task sampling gives remote staff feedback from observable examples rather than a vague impression of performance or workload.', sections: [{ title: 'Set the sample before review', paragraphs: [aug17Source[7][4], aug17Source[7][5]], checks: ['What population is sampled?', 'What is the pass criterion?', 'Who decides role expectations?'] }, { title: 'Use patterns carefully', paragraphs: [aug17Source[7][6]], checks: ['Is the issue isolated or recurring?', 'Did the sample miss a known risk?', 'Where are sensitive conclusions stored?'] }] },
  'philippines-outsourced-vendor-follow-up-aging': { intro: 'Vendor follow-up aging should preserve the vendor’s source commitment without turning an unconfirmed date into a commercial promise.', sections: [{ title: 'Track the commitment', paragraphs: [aug17Source[8][4], aug17Source[8][5]], checks: ['What did the vendor actually confirm?', 'Which reminder is approved?', 'Who owns acceptance or escalation?'] }, { title: 'Review repeated delay', paragraphs: [aug17Source[8][6]], checks: ['Which request types age?', 'What evidence closes the item?', 'Who decides the commercial response?'] }] },
  'philippines-virtual-assistant-calendar-decision-log': { intro: 'A calendar decision log records scheduling tradeoffs so a Philippines-based assistant can prepare options without quietly making commitments.', sections: [{ title: 'Capture the conflict', paragraphs: [aug17Source[9][4], aug17Source[9][5]], checks: ['Which priority came from the owner?', 'What event detail must stay private?', 'Who approves the move?'] }, { title: 'Improve the standing rule', paragraphs: [aug17Source[9][6]], checks: ['Which conflict recurs?', 'What decision was made?', 'When should the rule be revisited?'] }] },
  'philippines-outsourced-crm-field-ownership': { intro: 'CRM field ownership prevents cleanup work from creating competing versions of customer truth across a Philippines-based support lane.', sections: [{ title: 'Assign authoritative fields', paragraphs: [aug17Source[10][4], aug17Source[10][5]], checks: ['Which source governs?', 'What may support edit?', 'Who approves lifecycle changes?'] }, { title: 'Trace material corrections', paragraphs: [aug17Source[10][6]], checks: ['Which fields disagree repeatedly?', 'What source resolved the conflict?', 'What change note is required?'] }] },
  'philippines-remote-team-absence-handoff': { intro: 'An absence handoff keeps recurring work moving while limiting the availability detail shared with people who only need task context.', sections: [{ title: 'Prepare the backup view', paragraphs: [aug17Source[11][4], aug17Source[11][5]], checks: ['Which tasks are active?', 'What information is unnecessary?', 'Who decides reassignment?'] }, { title: 'Close the handoff', paragraphs: [aug17Source[11][6]], checks: ['Did the backup have enough context?', 'Which ownership gap appeared?', 'What changes before the next absence?'] }] },
  'philippines-outsourced-inbox-response-boundaries': { intro: 'Inbox response boundaries make it obvious when a Philippines-based role may sort or draft and when the owner must approve or send.', sections: [{ title: 'Classify message risk', paragraphs: [aug17Source[12][4], aug17Source[12][5]], checks: ['Does the message carry a commitment?', 'Which response channel is approved?', 'Who handles confidential details?'] }, { title: 'Review routing decisions', paragraphs: [aug17Source[12][6]], checks: ['Was context sufficient?', 'Which case exposed a gap?', 'Who approves a new boundary?'] }] },
  'philippines-virtual-assistant-source-document-index': { intro: 'A source-document index gives a virtual assistant a safe way to find evidence without inventing authority for an uncertain or conflicting file.', sections: [{ title: 'Record provenance', paragraphs: [aug17Source[13][4], aug17Source[13][5]], checks: ['Which location is authoritative?', 'What status does the file have?', 'Who decides retention or deletion?'] }, { title: 'Hold uncertain matches', paragraphs: [aug17Source[13][6]], checks: ['What makes a possible duplicate?', 'Which correction is traceable?', 'Who resolves conflicting sources?'] }] },
  'philippines-outsourced-customer-support-escalation-quality': { intro: 'Escalation quality is measured by whether an owner can act on the facts, not by how quickly a support worker forwards an incomplete conclusion.', sections: [{ title: 'Require actionable evidence', paragraphs: [aug17Source[14][4], aug17Source[14][5]], checks: ['Is the customer or order identified?', 'What approved step was attempted?', 'Which decision belongs to the owner?'] }, { title: 'Sample for completeness', paragraphs: [aug17Source[14][6]], checks: ['Which field is often missing?', 'Does speed reward incomplete work?', 'What checklist change is justified?'] }] },
  'philippines-remote-operations-status-brief': { intro: 'A remote operations status brief separates completed work, blocked work, risk, and decisions so a manager can act on the current state.', sections: [{ title: 'State the period and evidence', paragraphs: [aug17Source[15][4], aug17Source[15][5]], checks: ['What is actually complete?', 'Which item is blocked?', 'Who decides the response to risk?'] }, { title: 'Carry patterns forward', paragraphs: [aug17Source[15][6]], checks: ['Which blocker repeats?', 'Are definitions stable?', 'Where is the supporting record?'] }] },
  'philippines-outsourced-website-content-ownership': { intro: 'Website content ownership keeps routine support work separate from changing a public claim, promise, or audience-facing decision.', sections: [{ title: 'Map page authority', paragraphs: [aug17Source[16][4], aug17Source[16][5]], checks: ['Who owns the page?', 'Which changes are formatting only?', 'What requires publication approval?'] }, { title: 'Review high-use pages', paragraphs: [aug17Source[16][6]], checks: ['What source supports the page?', 'When is the next review?', 'What happens if ownership is missing?'] }] },
  'philippines-virtual-assistant-work-queue-priority-rules': { intro: 'Work-queue priority rules help a virtual assistant sort competing requests without turning urgency into an unapproved external commitment.', sections: [{ title: 'Use observable priority inputs', paragraphs: [aug17Source[17][4], aug17Source[17][5]], checks: ['What evidence supports urgency?', 'Which work is waiting for the owner?', 'Who may change priority?'] }, { title: 'Review reversals', paragraphs: [aug17Source[17][6]], checks: ['Which priorities were reversed?', 'What became overdue?', 'Which recurring exception needs a written rule?'] }] },
  'philippines-outsourced-operations-reconciliation-notes': { intro: 'Operations reconciliation notes make mismatched records reviewable without erasing a difference or pretending the support lane can decide which source wins.', sections: [{ title: 'Compare defined sources', paragraphs: [aug17Source[18][4], aug17Source[18][5]], checks: ['Which fields are matched?', 'What difference is observed?', 'Who decides the governing source?'] }, { title: 'Preserve the resolution', paragraphs: [aug17Source[18][6]], checks: ['Which cause recurs?', 'What evidence supports correction?', 'What action follows approval?'] }] },
  'philippines-remote-team-recurring-task-ownership': { intro: 'Recurring-task ownership prevents distributed work from becoming everyone’s responsibility and no one’s accountable handoff.', sections: [{ title: 'Name the recurring unit', paragraphs: [aug17Source[19][4], aug17Source[19][5]], checks: ['What triggers the task?', 'Who is the backup?', 'What happens when the window is missed?'] }, { title: 'Review missed work', paragraphs: [aug17Source[19][6]], checks: ['Was the trigger clear?', 'Which owner decision is needed?', 'When may a stale task be retired?'] }] },
  'philippines-outsourced-admin-approval-queue': { intro: 'An admin approval queue keeps a request moving with complete context while leaving the decision, commitment, and exception with the authorized owner.', sections: [{ title: 'Build a decision-ready packet', paragraphs: [aug17Source[20][4], aug17Source[20][5]], checks: ['What decision is requested?', 'What evidence is missing?', 'Who is the approver?'] }, { title: 'Close the right way', paragraphs: [aug17Source[20][6]], checks: ['Why did the item wait?', 'What record proves the decision?', 'Was the request withdrawn by its owner?'] }] },
  'philippines-virtual-assistant-handoff-evidence': { intro: 'Handoff evidence lets a virtual assistant pass work across working windows without making the next person reconstruct the missing context.', sections: [{ title: 'Write the next useful action', paragraphs: [aug17Source[21][4], aug17Source[21][5]], checks: ['What is the current state?', 'Which evidence is linked?', 'Who owns the next action?'] }, { title: 'Test the handoff', paragraphs: [aug17Source[21][6]], checks: ['Could the next person start?', 'Which question repeated?', 'What boundary needs clarification?'] }] },
} as Record<string, { intro: string; sections: { title: string; paragraphs: string[]; checks: string[] }[] }>;
